module TopModule (
    input  logic clk,
    input  logic a,
    input  logic b,
    output logic out_assign,
    output logic out_always_comb,
    output logic out_always_ff
);

    // 1. XOR using continuous assignment
    assign out_assign = a ^ b;

    // 2. XOR using a combinational always block
    always_comb begin
        out_always_comb = a ^ b;
    end

    // 3. XOR using a clocked always block (sequential, registers output)
    always_ff @(posedge clk) begin
        out_always_ff <= a ^ b;
    end

endmodule

